-- Nashville Transaction Import from Chris's Bookings workbook
-- 4,031 transactions, $9.47M total
-- Tenant: 489ace07-1a6b-4864-833a-4f8420568b40

CREATE TABLE IF NOT EXISTS payment_transactions (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id UUID NOT NULL,
  payment_date DATE,
  client_name TEXT,
  lname TEXT,
  fname TEXT,
  associate TEXT,
  deposit_account TEXT,
  amount NUMERIC(12,2),
  service_type TEXT,
  notes TEXT,
  status TEXT DEFAULT 'No Status',
  client_id TEXT REFERENCES clients(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

ALTER TABLE payment_transactions ENABLE ROW LEVEL SECURITY;
CREATE POLICY crm_open_payment_transactions ON payment_transactions
  FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);

CREATE INDEX IF NOT EXISTS idx_payment_transactions_tenant ON payment_transactions(tenant_id);
CREATE INDEX IF NOT EXISTS idx_payment_transactions_lname ON payment_transactions(lname);
CREATE INDEX IF NOT EXISTS idx_payment_transactions_client ON payment_transactions(client_id);

GRANT ALL ON payment_transactions TO service_role;

-- Import all 4031 transactions

-- Auto-match transactions to clients by last name (fuzzy)
UPDATE payment_transactions pt
SET client_id = c.id
FROM clients c
WHERE c.tenant_id = pt.tenant_id
  AND pt.client_id IS NULL
  AND pt.lname IS NOT NULL
  AND pt.lname != ''
  AND LOWER(c.name) LIKE '%' || LOWER(pt.lname) || '%';

-- Summary
SELECT status, COUNT(*) as count, SUM(amount) as total
FROM payment_transactions
WHERE tenant_id = '489ace07-1a6b-4864-833a-4f8420568b40'
GROUP BY status
ORDER BY total DESC NULLS LAST;